import {packingTotals} from './packing-math.js';
export const PRODUCT_HEADERS=['Code','NAME','Barcode','Supplier CTN','Supplier Size','TOTAL PCS (Supplier)','RP Unit','PACKSIZE (Ninso)','TOTAL CTN (Ninso)','PACKING MATERIAL','OUTER','PACKING FEE'];
export const PEOPLE_HEADERS=['NO','ID','NAME','Short Name','IC','Password','Role','Additional Pay / PCS','Status'];
export const productSample=['D215032','LUX VELVET TOUCH BAR SOAP 70G 1S','8999999527679','1','144','144','2','72','1','TAPE','CUT','0.05'];
export const personSample=['1','PK01','Example Packer','Packer 1','001234-00-0000','','Packer','0.02','Active'];
const norm=s=>String(s).replace(/^\ufeff/,'').toLowerCase().replace(/[^a-z0-9]/g,'');
export function parseCSV(text){const rows=[];let row=[],cell='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(c==='"'){if(quoted&&text[i+1]==='"'){cell+='"';i++;}else quoted=!quoted;}else if(c===','&&!quoted){row.push(cell);cell='';}else if((c==='\n'||c==='\r')&&!quoted){if(c==='\r'&&text[i+1]==='\n')i++;row.push(cell);if(row.some(x=>x.trim()))rows.push(row);row=[];cell='';}else cell+=c;}if(quoted)throw Error('CSV contains an unclosed quote.');row.push(cell);if(row.some(x=>x.trim()))rows.push(row);return rows;}
export function objectsFromCSV(text){const rows=parseCSV(text);if(rows.length<2)throw Error('CSV contains no records.');const headers=rows.shift();if(new Set(headers.map(norm)).size!==headers.length)throw Error('CSV contains duplicate column names.');return rows.map((row,i)=>{if(row.length!==headers.length)throw Error(`Row ${i+2}: column count does not match the header.`);return Object.fromEntries(headers.map((h,n)=>[h,norm(h)==='password'?row[n]:row[n].trim()]));});}
function field(o,...names){const entries=Object.entries(o);for(const n of names){const found=entries.find(([key])=>norm(key)===norm(n));if(found)return String(found[1]??'').trim();}return '';}
function number(v,label,defaultValue){if(v===''&&defaultValue!==undefined)return defaultValue;if(!/^\d+(\.\d+)?$/.test(v.replaceAll(',','')))throw Error(`${label}: enter a non-negative number.`);return Number(v.replaceAll(',',''));}
export function micros(v){if(!/^\d+(\.\d{1,6})?$/.test(v))throw Error('Pay must be non-negative, with at most 6 decimal places.');const [whole,decimal='']=v.split('.');const result=Number(whole)*1000000+Number(decimal.padEnd(6,'0'));if(!Number.isSafeInteger(result))throw Error('Pay value is too large.');return result;}
export function roleCode(value){const v=norm(value);if(['logisticsstaff','logistics','driver'].includes(v))return 'driver';if(['packer','packingstaff'].includes(v))return 'packer';if(['admin','administration','administrator'].includes(v))return 'admin';throw Error('Role must be Logistics Staff, Packer or Admin.');}
export function roleLabel(role){return {driver:'Logistics Staff',packer:'Packer',admin:'Admin'}[role]||role;}
export function mapProduct(o,previous,id){const code=field(o,'Code'),name=field(o,'NAME'),barcode=field(o,'Barcode');if(!code||!name)throw Error('Code and NAME are required.');if(/[eE][+-]?\d+$/.test(barcode)||/\.0$/.test(barcode))throw Error('Barcode must be text, not scientific notation or a decimal.');const supplierSize=number(field(o,'Supplier Size','supplierSize'),'Supplier Size'),rpUnit=number(field(o,'RP Unit','rpUnit'),'RP Unit'),ninsoSize=number(field(o,'PACKSIZE (Ninso)','ninsoSize'),'PACKSIZE (Ninso)');for(const [label,v] of [['Supplier Size',supplierSize],['RP Unit',rpUnit],['PACKSIZE (Ninso)',ninsoSize]])if(!Number.isSafeInteger(v)||v<1)throw Error(`${label} must be a positive whole number.`);const referenceCtn=number(field(o,'Supplier CTN'),'Supplier CTN',1);if(!Number.isSafeInteger(referenceCtn)||referenceCtn<1)throw Error('Supplier CTN must be a positive whole number.');const {totalSupplierPcs,totalNinsoCtn}=packingTotals({supplierSize,rpUnit,ninsoSize},referenceCtn);for(const [label,expected] of [['TOTAL PCS (Supplier)',totalSupplierPcs],['TOTAL CTN (Ninso)',totalNinsoCtn]]){const provided=field(o,label);if(provided!==''&&Math.abs(number(provided,label)-expected)>Math.max(0.000001,Math.abs(expected)*0.000001))throw Error(`${label} does not match the pack-size calculation.`);}return {...previous,id:previous?.id||id,code,name,barcode,supplierSize,rpUnit,ninsoSize,referenceCtn,totalSupplierPcs,totalNinsoCtn,rateMicros:micros(field(o,'PACKING FEE','rate')),bag:field(o,'PACKING MATERIAL','bag'),outer:field(o,'OUTER'),active:previous?.active??true};}
export function mapPerson(o,previous){const id=field(o,'ID'),name=field(o,'NAME');if(!/^[A-Za-z0-9_.-]{1,60}$/.test(id)||!name)throw Error('A valid ID and NAME are required.');const status=field(o,'Status')||'Active',v=norm(status);if(!['active','inactive','true','false','1','0','enabled','disabled'].includes(v))throw Error('Status must be Active or Inactive.');const shortNameProvided=Object.keys(o).some(k=>norm(k)==='shortname');const person={...previous,id,name,shortName:shortNameProvided?field(o,'Short Name'):(previous?.shortName||''),no:field(o,'NO'),ic:field(o,'IC'),role:roleCode(field(o,'Role')),extraMicros:micros(field(o,'Additional Pay / PCS','extraRate')||'0'),active:['active','true','1','enabled'].includes(v)};const password=String(Object.entries(o).find(([key])=>norm(key)==='password')?.[1]??'');if(password&&password.length<6)throw Error('Initial password must be at least 6 characters.');return {person,password,shortNameProvided};}

export function accountCSV(rows){return '\ufeff'+rows.map(row=>row.map(v=>'\"'+String(v??'').replaceAll('\"','\"\"')+'\"').join(',')).join('\r\n');}
